import math
import random
class Counted(int):
    """A whole number that counts how often it is compared with another number."""
    comparisons = 0
    def __lt__(self, other):
        Counted.comparisons += 1
        return int.__lt__(self, other)
    def __le__(self, other):
        Counted.comparisons += 1
        return int.__le__(self, other)
    def __gt__(self, other):
        Counted.comparisons += 1
        return int.__gt__(self, other)
    def __ge__(self, other):
        Counted.comparisons += 1
        return int.__ge__(self, other)
    def __neg__(self):
        return Counted(-int(self))
def few_comparisons(n, k, per_number):
    # Calls kth_largest on the numbers 0..n-1 in a shuffled order, wrapped so that every comparison between two numbers is counted.
    values = list(range(n))
    random.Random(5).shuffle(values)
    numbers = [Counted(v) for v in values]
    Counted.comparisons = 0
    answer = kth_largest(numbers, k)
    used = Counted.comparisons
    assert answer == n - k, f"kth_largest returned {answer!r} for the shuffled numbers 0..{n - 1} and k = {k}; expected {n - k}"
    limit = per_number * n
    assert used <= limit, (f"your code compared numbers {used:,} times on {n:,} numbers (k = {k}); this test allows {limit:,}, "
                           f"and sorting everything needs about {int(n * math.log2(n)):,}. Keep only the k largest as you go.")
